let startTime = Date.now();
try {
  startTime = $('Webhook').first().json.headers['x-request-start'];
} catch(e) {
  // Ignore missing webhook node
}
const duration = Date.now() - (parseInt(startTime) || Date.now());

const payload = {
  workflow_id: $workflow.id,
  workflow_name: $workflow.name,
  agent_id: $('Log Content Performance').first().json.body?.agent_id || $('Log Content Performance').first().json.agent_id || 'system',
  duration_ms: duration,
  api_calls: $('Log Content Performance').first().json.body?.api_call_count || $('Log Content Performance').first().json.api_call_count || 0,
  cost_usd: $('Log Content Performance').first().json.body?.total_cost || $('Log Content Performance').first().json.total_cost || 0,
  outcome: $('Log Content Performance').first().json.body?.outcome || $('Log Content Performance').first().json.outcome || 'completed',
  outcome_count: $('Log Content Performance').first().json.body?.result_count || $('Log Content Performance').first().json.result_count || 0,
  quality_score: $('Log Content Performance').first().json.body?.quality_score || $('Log Content Performance').first().json.quality_score || null,
  status: 'success',
  metadata: JSON.stringify({ source: 'n8n_auto_log', doc_title: $('Log Content Performance').first().json.body?.doc_title, target_channel: $('Log Content Performance').first().json.body?.target_channel, doc_url: $('Log Content Performance').first().json.body?.doc_url })
};

const response = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://gojpffsrxybbpbdzzrvs.supabase.co/rest/v1/workflow_runs',
  headers: {
    'apikey': '{{SUPABASE_SERVICE_ROLE_KEY}}',
    'Authorization': 'Bearer {{SUPABASE_SERVICE_ROLE_KEY}}',
    'Content-Type': 'application/json',
    'Prefer': 'return=representation'
  },
  body: payload,
  json: true
});

return [{ json: { logged: true, ...payload } }];
